colossal_leviathan.source:
export const envelope = [44, 48, 44];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 8;
  const grid = new Uint8Array(W * H * D);

  // Palette ID mappings
  const PALETTE = [
    null,                               // 0: Air
    "minecraft:dark_prismarine",        // 1: Primary dark carapace
    "minecraft:prismarine_bricks",      // 2: Scaled masonry / armor plate
    "minecraft:prismarine",             // 3: Ventral belly skin
    "minecraft:cyan_terracotta",        // 4: Smooth underbelly hide
    "minecraft:warped_wart_block",      // 5: Abyssal fleshy muscle / gullet
    "minecraft:sea_lantern",            // 6: Luminous bioluminescence / eye glow
    "minecraft:pearlescent_froglight",  // 7: Blazing primary eye core
    "minecraft:bone_block",             // 8: Chitinous horns / fangs / spikes
    "minecraft:crying_obsidian",        // 9: Abyssal maw depth / void runes
    "minecraft:deepslate_tiles",        // 10: Heavy armored dorsal scutes
    "minecraft:oxidized_cut_copper",    // 11: Weathered verdigris chitin
    "minecraft:blackstone",             // 12: Dark spine crests
    "minecraft:verdant_froglight",      // 13: Secondary luminous eyes
  ];

  function idx(x, y, z) {
    return x + y * W + z * W * H;
  }

  function setVoxel(x, y, z, id) {
    const ix = Math.floor(x);
    const iy = Math.floor(y);
    const iz = Math.floor(z);
    if (ix >= 0 && ix < W && iy >= 0 && iy < H && iz >= 0 && iz < D) {
      grid[idx(ix, iy, iz)] = id;
    }
  }

  function getVoxel(x, y, z) {
    const ix = Math.floor(x);
    const iy = Math.floor(y);
    const iz = Math.floor(z);
    if (ix >= 0 && ix < W && iy >= 0 && iy < H && iz >= 0 && iz < D) {
      return grid[idx(ix, iy, iz)];
    }
    return 0;
  }

  // Draw an ellipsoid with custom shader callback
  function drawEllipsoid(cx, cy, cz, rx, ry, rz, materialFn) {
    const minX = Math.max(0, Math.floor(cx - rx));
    const maxX = Math.min(W - 1, Math.ceil(cx + rx));
    const minY = Math.max(0, Math.floor(cy - ry));
    const maxY = Math.min(H - 1, Math.ceil(cy + ry));
    const minZ = Math.max(0, Math.floor(cz - rz));
    const maxZ = Math.min(D - 1, Math.ceil(cz + rz));

    const invRx2 = 1 / (rx * rx);
    const invRy2 = 1 / (ry * ry);
    const invRz2 = 1 / (rz * rz);

    for (let x = minX; x <= maxX; x++) {
      const dx = x - cx;
      const dxx = dx * dx * invRx2;
      for (let z = minZ; z <= maxZ; z++) {
        const dz = z - cz;
        const dzz = dz * dz * invRz2;
        if (dxx + dzz > 1.05) continue;
        for (let y = minY; y <= maxY; y++) {
          const dy = y - cy;
          const distSq = dxx + dzz + dy * dy * invRy2;
          if (distSq <= 1.0) {
            const blockId = materialFn(x, y, z, dx, dy, dz, distSq);
            if (blockId > 0) {
              grid[idx(x, y, z)] = blockId;
            }
          }
        }
      }
    }
  }

  // Draw sphere along splines
  function drawSphere(cx, cy, cz, r, materialFn) {
    drawEllipsoid(cx, cy, cz, r, r, r, materialFn);
  }

  // Catmull-Rom spline interpolation for organic curves
  function interpolateSpline(points, stepsPerSegment = 12) {
    const result = [];
    const n = points.length;
    for (let i = 0; i < n - 1; i++) {
      const p0 = points[Math.max(0, i - 1)];
      const p1 = points[i];
      const p2 = points[i + 1];
      const p3 = points[Math.min(n - 1, i + 2)];

      for (let s = 0; s < stepsPerSegment; s++) {
        const t = s / stepsPerSegment;
        const t2 = t * t;
        const t3 = t2 * t;

        const x = 0.5 * (2 * p1[0] + (-p0[0] + p2[0]) * t + (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 + (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3);
        const y = 0.5 * (2 * p1[1] + (-p0[1] + p2[1]) * t + (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 + (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3);
        const z = 0.5 * (2 * p1[2] + (-p0[2] + p2[2]) * t + (2 * p0[2] - 5 * p1[2] + 4 * p2[2] - p3[2]) * t2 + (-p0[2] + 3 * p1[2] - 3 * p2[2] + p3[2]) * t3);
        const r = 0.5 * (2 * p1[3] + (-p0[3] + p2[3]) * t + (2 * p0[3] - 5 * p1[3] + 4 * p2[3] - p3[3]) * t2 + (-p0[3] + 3 * p1[3] - 3 * p2[3] + p3[3]) * t3);

        result.push({ x, y, z, r, tag: p1[4] || 0 });
      }
    }
    const last = points[n - 1];
    result.push({ x: last[0], y: last[1], z: last[2], r: last[3], tag: last[4] || 0 });
    return result;
  }

  function renderSpline(splinePoints, steps, materialFn) {
    const samples = interpolateSpline(splinePoints, steps);
    for (const p of samples) {
      drawSphere(p.x, p.y, p.z, p.r, (x, y, z, dx, dy, dz, distSq) => materialFn(x, y, z, dx, dy, dz, distSq, p));
    }
  }

  // Material Shader for Serpentine Leviathan Body
  function bodyMaterial(x, y, z, dx, dy, dz, distSq, sample) {
    const isSurface = distSq > 0.45;
    const isVentral = dy < 0.2 && dz < 0.3; // Belly / underside
    const isDorsal = dy >= 0.2 || dz >= 0.3;  // Back / armored spine

    // Bioluminescent striping along ventral side
    if (isVentral && isSurface) {
      const stripePhase = Math.sin((x * 0.8 + y * 1.2 + z * 0.9));
      if (stripePhase > 0.75) {
        return 6; // Sea lantern
      }
      if (stripePhase > 0.4) {
        return 5; // Warped wart fleshy margins
      }
      return ((x + y + z) % 4 === 0) ? 4 : 3; // Cyan terracotta / prismarine
    }

    if (isDorsal && isSurface) {
      // Chitinous armored scales and ridges
      const scutePattern = (Math.floor(x * 0.7) + Math.floor(y * 0.7) + Math.floor(z * 0.7)) % 5;
      if (scutePattern === 0) return 10; // Deepslate tiles
      if (scutePattern === 1) return 11; // Oxidized copper
      if (scutePattern === 2) return 2;  // Prismarine bricks
      return 1; // Dark prismarine
    }

    // Dense inner core
    if (distSq > 0.2) return 1;
    return 5; // Warped wart interior muscle
  }

  // 1. Monolithic Deep-Sea Base (joining all breaches into one unified foundation)
  drawEllipsoid(22, 6, 26, 14, 4.5, 12, (x, y, z, dx, dy, dz) => {
    if (dy < 0) return 10; // Deepslate bedrock anchor
    return (dx * dx + dz * dz > 80) ? 1 : 2;
  });

  // 2. Main Rearing Torso & Neck (Breaching toward -Z waterfront)
  const mainSpine = [
    [22, 5, 26, 6.4],
    [22, 11, 23, 6.0],
    [22, 18, 19, 5.3],
    [22, 25, 14, 4.6],
    [22, 31, 10, 4.1],
    [22, 34, 7, 3.8], // Skull center
  ];
  renderSpline(mainSpine, 14, bodyMaterial);

  // 3. Colossal Skull & Jaws (Gaping Maw facing North / -Z)
  // Skull Crown
  drawEllipsoid(22, 35, 7, 4.4, 3.6, 4.6, (x, y, z, dx, dy, dz, distSq) => {
    if (dy > 1.2 && distSq > 0.5) return 10; // Armored brow
    if (dz < -2.0) return 1;
    return bodyMaterial(x, y, z, dx, dy, dz, distSq);
  });

  // Upper Jaw (Snout)
  const upperJawSpline = [
    [22, 34.5, 7, 3.8],
    [22, 35.2, 4, 3.0],
    [22, 35.5, 1.8, 2.0],
  ];
  renderSpline(upperJawSpline, 10, (x, y, z, dx, dy, dz, distSq) => {
    if (dy > 0.5) return 10; // Chitin snout plate
    if (dy < -0.6) return 1;
    return 1;
  });

  // Lower Jaw (Mandible)
  const lowerJawSpline = [
    [22, 30.5, 8.5, 3.4],
    [22, 28.5, 5.5, 2.8],
    [22, 26.5, 2.2, 1.9],
  ];
  renderSpline(lowerJawSpline, 10, (x, y, z, dx, dy, dz, distSq) => {
    if (dy < -0.4) return 10; // Armored underchin
    return 1;
  });

  // Carve Maw Cavity (Hollow throat and glowing abyss inside)
  for (let z = 2; z <= 9; z++) {
    for (let y = 27; y <= 33; y++) {
      for (let x = 18; x <= 26; x++) {
        const dx = (x - 22) / 3.4;
        const dy = (y - 30.8) / 2.5;
        const dist2 = dx * dx + dy * dy;
        if (dist2 <= 1.0) {
          if (z >= 8) {
            // Glowing gullet abyss
            setVoxel(x, y, z, (dist2 < 0.3) ? 6 : 9); // Sea lantern / crying obsidian
          } else if (z >= 6 && y === 28) {
            setVoxel(x, y, z, 5); // Fleshy tongue
          } else {
            setVoxel(x, y, z, 0); // Open agape mouth air
          }
        }
      }
    }
  }

  // Razor Sharp Teeth & Saber Tusks
  for (let z = 2; z <= 7; z++) {
    // Upper teeth along jaw margin
    const upperW = 2.4 + (z - 2) * 0.3;
    setVoxel(22 - upperW, 33, z, 8);
    setVoxel(22 + upperW, 33, z, 8);

    // Lower teeth along mandible margin
    const lowerW = 1.9 + (z - 2) * 0.3;
    setVoxel(22 - lowerW, 28, z, 8);
    setVoxel(22 + lowerW, 28, z, 8);
  }
  // Colossal Snout Saber Fangs
  setVoxel(20, 32, 2, 8);
  setVoxel(20, 31, 2, 8);
  setVoxel(24, 32, 2, 8);
  setVoxel(24, 31, 2, 8);

  // Mandible Impaling Tusks
  setVoxel(21, 29, 2, 8);
  setVoxel(23, 29, 2, 8);

  // 4. Multiple Luminous Eyes
  // Colossal Primary Eyes (Left & Right)
  // Left Primary Eye
  setVoxel(17, 34, 6, 7); // Froglight core
  setVoxel(17, 34, 5, 6);
  setVoxel(17, 35, 6, 6);
  setVoxel(17, 33, 6, 6);
  setVoxel(17, 34, 7, 6);
  setVoxel(16, 34, 6, 10); // Deepslate orbit socket

  // Right Primary Eye
  setVoxel(27, 34, 6, 7); // Froglight core
  setVoxel(27, 34, 5, 6);
  setVoxel(27, 35, 6, 6);
  setVoxel(27, 33, 6, 6);
  setVoxel(27, 34, 7, 6);
  setVoxel(28, 34, 6, 10); // Deepslate orbit socket

  // Secondary Temple Eye Clusters (Ancient Multi-Eyed Visage)
  setVoxel(16, 35, 8, 13); // Left verdant eye
  setVoxel(15, 34, 10, 13);
  setVoxel(16, 32, 11, 6);

  setVoxel(28, 35, 8, 13); // Right verdant eye
  setVoxel(29, 34, 10, 13);
  setVoxel(28, 32, 11, 6);

  // Occult Crown Eye (Center Forehead)
  setVoxel(22, 37, 5, 6);
  setVoxel(22, 38, 5, 8); // Chitinous brow crest over eye

  // 5. Massive Cranial Horns & Spikes
  // Center Crown Horn
  const centerHorn = [
    [22, 37, 7, 1.8],
    [22, 40, 10, 1.5],
    [22, 43, 14, 1.1],
    [22, 46, 18, 0.7],
  ];
  renderSpline(centerHorn, 8, (x, y, z, dx, dy, dz, distSq) => (distSq > 0.5 ? 8 : 10));

  // Left Sweeping Brow Horn
  const leftHorn = [
    [19, 36, 8, 1.6],
    [16, 39, 10, 1.4],
    [13, 42, 13, 1.0],
    [11, 45, 17, 0.6],
  ];
  renderSpline(leftHorn, 8, (x, y, z, dx, dy, dz, distSq) => (distSq > 0.4 ? 8 : 10));

  // Right Sweeping Brow Horn
  const rightHorn = [
    [25, 36, 8, 1.6],
    [28, 39, 10, 1.4],
    [31, 42, 13, 1.0],
    [33, 45, 17, 0.6],
  ];
  renderSpline(rightHorn, 8, (x, y, z, dx, dy, dz, distSq) => (distSq > 0.4 ? 8 : 10));

  // Mandible Chin Barbels / Sensory Spines
  const centerBarbel = [
    [22, 25, 3, 1.2],
    [22, 21, 2, 0.9],
    [22, 17, 1, 0.5],
  ];
  renderSpline(centerBarbel, 6, () => 8);

  const leftBarbel = [
    [19, 25, 4, 1.0],
    [17, 21, 3, 0.7],
    [15, 17, 2, 0.4],
  ];
  renderSpline(leftBarbel, 6, () => 8);

  const rightBarbel = [
    [25, 25, 4, 1.0],
    [27, 21, 3, 0.7],
    [29, 17, 2, 0.4],
  ];
  renderSpline(rightBarbel, 6, () => 8);

  // 6. Left Serpentine Breaching Coil (Coil Alpha)
  const leftCoil = [
    [20, 6, 24, 5.2],
    [14, 10, 26, 4.4],
    [9, 16, 29, 4.0], // High left crest
    [8, 14, 34, 3.7],
    [12, 7, 37, 4.3],
    [18, 5, 38, 4.8],
  ];
  renderSpline(leftCoil, 12, bodyMaterial);

  // Spines on Left Coil
  const leftSpines = [
    [11, 19, 27, 1.2],
    [8, 22, 29, 1.0],
    [7, 20, 32, 0.9],
    [8, 17, 35, 0.8],
  ];
  for (const s of leftSpines) {
    drawEllipsoid(s[0], s[1], s[2], s[3], s[3] * 2.2, s[3], () => 8);
  }

  // 7. Right Serpentine Breaching Coil (Coil Beta)
  const rightCoil = [
    [24, 6, 23, 5.4],
    [31, 11, 25, 4.8],
    [36, 18, 28, 4.2], // Towering right crest
    [36, 15, 33, 3.8],
    [32, 7, 37, 4.4],
    [26, 5, 38, 5.0],
  ];
  renderSpline(rightCoil, 12, bodyMaterial);

  // Spines on Right Coil
  const rightSpines = [
    [33, 21, 25, 1.2],
    [37, 24, 28, 1.1],
    [37, 22, 31, 1.0],
    [34, 19, 34, 0.8],
  ];
  for (const s of rightSpines) {
    drawEllipsoid(s[0], s[1], s[2], s[3], s[3] * 2.5, s[3], () => 8);
  }

  // 8. Thrashing Caudal Tail & Monster Flukes (Rear)
  const tailSpline = [
    [22, 6, 36, 4.8],
    [22, 12, 38, 4.0],
    [23, 19, 40, 3.3],
    [22, 26, 40, 2.5],
    [22, 32, 39, 1.8], // Tail tip
  ];
  renderSpline(tailSpline, 10, bodyMaterial);

  // Tail Flukes & Fin Blades
  // Dorsal Tail Blade
  const tailDorsalFin = [
    [22, 26, 40, 1.5],
    [22, 31, 41, 1.2],
    [22, 36, 41, 0.8],
    [22, 39, 40, 0.5],
  ];
  renderSpline(tailDorsalFin, 6, () => 8);

  // Left Caudal Fluke
  const leftFluke = [
    [22, 27, 40, 1.8],
    [17, 28, 41, 1.4],
    [13, 30, 41, 1.0],
    [9, 31, 42, 0.6],
  ];
  renderSpline(leftFluke, 6, (x, y, z, dx, dy, dz, distSq) => (distSq > 0.4 ? 8 : 10));

  // Right Caudal Fluke
  const rightFluke = [
    [22, 27, 40, 1.8],
    [27, 28, 41, 1.4],
    [31, 30, 41, 1.0],
    [35, 31, 42, 0.6],
  ];
  renderSpline(rightFluke, 6, (x, y, z, dx, dy, dz, distSq) => (distSq > 0.4 ? 8 : 10));

  // 9. Colossal Grasping Talons / Pier-Crushing Pectoral Scythes
  // Left Striking Scythe
  const leftScythe = [
    [17, 20, 16, 2.8],
    [12, 17, 12, 2.3],
    [8, 13, 8, 1.8],
    [5, 9, 5, 1.4],
    [4, 6, 2, 1.0],
    [3, 3, 1, 0.6], // Claws striking North waterfront
  ];
  renderSpline(leftScythe, 8, (x, y, z, dx, dy, dz, distSq, sample) => {
    if (sample.r <= 1.2) return 8; // Razor bone claw blade
    return bodyMaterial(x, y, z, dx, dy, dz, distSq, sample);
  });
  // Left Scythe Elbow Horn
  drawEllipsoid(8, 15, 7, 0.8, 1.8, 0.8, () => 8);

  // Right Striking Scythe
  const rightScythe = [
    [27, 20, 16, 2.8],
    [32, 17, 12, 2.3],
    [36, 13, 8, 1.8],
    [39, 9, 5, 1.4],
    [40, 6, 2, 1.0],
    [41, 3, 1, 0.6], // Claws striking North waterfront
  ];
  renderSpline(rightScythe, 8, (x, y, z, dx, dy, dz, distSq, sample) => {
    if (sample.r <= 1.2) return 8; // Razor bone claw blade
    return bodyMaterial(x, y, z, dx, dy, dz, distSq, sample);
  });
  // Right Scythe Elbow Horn
  drawEllipsoid(36, 15, 7, 0.8, 1.8, 0.8, () => 8);

  // 10. Low Sweeping Side Tendrils (Ribbons whipping across the bay surface)
  const leftTendril = [
    [12, 7, 20, 2.0],
    [7, 6, 16, 1.6],
    [4, 5, 11, 1.2],
    [2, 4, 6, 0.9],
    [1, 2, 2, 0.5],
  ];
  renderSpline(leftTendril, 6, bodyMaterial);

  const rightTendril = [
    [32, 7, 20, 2.0],
    [37, 6, 16, 1.6],
    [40, 5, 11, 1.2],
    [42, 4, 6, 0.9],
    [43, 2, 2, 0.5],
  ];
  renderSpline(rightTendril, 6, bodyMaterial);

  // Mid-Flank Ribbons
  const leftMidRibbon = [
    [10, 6, 28, 1.8],
    [5, 5, 27, 1.4],
    [2, 4, 24, 1.0],
    [1, 2, 21, 0.5],
  ];
  renderSpline(leftMidRibbon, 6, bodyMaterial);

  const rightMidRibbon = [
    [34, 6, 28, 1.8],
    [39, 5, 27, 1.4],
    [42, 4, 24, 1.0],
    [43, 2, 21, 0.5],
  ];
  renderSpline(rightMidRibbon, 6, bodyMaterial);

  // 11. Dorsal Armor Fins along Main Neck & Spine
  const dorsalFins = [
    [22, 23, 17, 1.2, 3.2],
    [22, 28, 14, 1.1, 3.5],
    [22, 17, 21, 1.3, 3.0],
    [22, 12, 25, 1.4, 2.8],
  ];
  for (const fin of dorsalFins) {
    drawEllipsoid(fin[0], fin[1], fin[2], fin[3], fin[4], fin[3], (x, y, z, dx, dy) => {
      if (dy > 1.0) return 8; // Bone fin edge
      return 10; // Deepslate scute
    });
  }

  // 12. Ground Conformance Pass (Rule 6 Compliance)
  // For every column occupied by the leviathan near the base, build down to terrain seabed
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      let yMin = -1;
      let yMax = -1;
      for (let y = 0; y < H; y++) {
        if (grid[idx(x, y, z)] !== 0) {
          if (yMin === -1) yMin = y;
          yMax = y;
        }
      }

      // If this column has body voxels touching down near the seat plane
      if (yMin !== -1 && yMin <= seatY + 4) {
        const hTerrain = api.heightAt(x, z);
        const targetGroundY = Math.max(0, Math.min(H - 1, seatY + hTerrain));

        // Seabed is lower: build thick abyssal footing down to meet it
        if (targetGroundY < yMin) {
          for (let y = targetGroundY; y < yMin; y++) {
            const blockId = ((x + y + z) % 4 === 0) ? 10 : (((x + z) % 3 === 0) ? 2 : 1);
            grid[idx(x, y, z)] = blockId;
          }
        }
        // Terrain rises higher: ensure solid foundation adheres into rising slope
        else if (targetGroundY > yMin && targetGroundY < yMax) {
          for (let y = yMin; y <= targetGroundY; y++) {
            if (grid[idx(x, y, z)] === 0) {
              grid[idx(x, y, z)] = 1;
            }
          }
        }
      }
    }
  }

  // 13. Emit Voxels to the World via api.set()
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const id = grid[idx(x, y, z)];
        if (id > 0 && PALETTE[id]) {
          api.set(x, y, z, PALETTE[id]);
        }
      }
    }
  }

  return {
    name: "Colossal Abyssal Leviathan",
    seatY: seatY,
    anchors: {
      front: [22, 34, 0],
      maw: [22, 30, 3],
      crown: [22, 46, 18],
      tail: [22, 32, 39],
      left_talon: [3, 3, 1],
      right_talon: [41, 3, 1],
    },
  };
}

guardian_colossus_apollo.source:
export const envelope = [21, 46, 21];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 8;
  const cx = 10;
  const cz = 10;

  function setB(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  }

  // Theme roles with robust classical Hellenistic fallbacks
  const stonePrimary = api.theme?.stone?.primary || "minecraft:smooth_quartz";
  const stoneAccent = api.theme?.stone?.accent || "minecraft:chiseled_quartz_block";
  const stoneStairs = api.theme?.stone?.stairs || "minecraft:quartz_stairs";
  const groundPlinth = api.theme?.ground?.plinth || "minecraft:quartz_pillar";
  const groundPavement = api.theme?.ground?.pavement || "minecraft:smooth_quartz";
  const groundRevetment = api.theme?.ground?.revetment || "minecraft:deepslate_bricks";

  // =========================================================================
  // 1. TERRAIN-CONFORMING FOUNDATION & PROMONTORY SKIRT
  // =========================================================================
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const dx = Math.abs(x - cx);
      const dz = Math.abs(z - cz);

      const inPedestal = (dx <= 8 && dz <= 8 && dx + dz <= 12);
      const inStairs = (x >= 8 && x <= 12 && z >= 14 && z <= 19);
      const inSkirt = (dx <= 9 && dz <= 9 && dx + dz <= 14);

      if (inPedestal || inStairs || inSkirt) {
        const rawH = Math.floor(api.heightAt(x, z));
