  setB(11, 39, 7, "minecraft:gold_block");
  setB(8, 39, 8, "minecraft:gold_block");
  setB(12, 39, 8, "minecraft:gold_block");
  setB(8, 39, 10, "minecraft:gold_block");
  setB(12, 39, 10, "minecraft:gold_block");
  setB(10, 39, 11, "minecraft:gold_block");

  // Corona Radiata Diadem
  for (let x = 9; x <= 11; x++) {
    for (let z = 8; z <= 10; z++) {
      setB(x, 40, z, "minecraft:gold_block");
    }
  }
  setB(10, 40, 7, "minecraft:ochre_froglight");

  // Seven Radiant Sun Rays
  // 1. North Ray
  setB(10, 41, 7, "minecraft:gold_block");
  setB(10, 42, 6, "minecraft:end_rod[facing=north]");
  setB(10, 43, 5, "minecraft:lightning_rod[facing=up]");

  // 2. North-West Ray
  setB(8, 41, 7, "minecraft:gold_block");
  setB(7, 42, 6, "minecraft:end_rod[facing=north]");
  setB(6, 43, 5, "minecraft:lightning_rod[facing=up]");

  // 3. North-East Ray
  setB(12, 41, 7, "minecraft:gold_block");
  setB(13, 42, 6, "minecraft:end_rod[facing=north]");
  setB(14, 43, 5, "minecraft:lightning_rod[facing=up]");

  // 4. West Ray
  setB(7, 41, 9, "minecraft:gold_block");
  setB(6, 42, 9, "minecraft:end_rod[facing=west]");
  setB(5, 43, 9, "minecraft:lightning_rod[facing=up]");

  // 5. East Ray
  setB(13, 41, 9, "minecraft:gold_block");
  setB(14, 42, 9, "minecraft:end_rod[facing=east]");
  setB(15, 43, 9, "minecraft:lightning_rod[facing=up]");

  // 6. South Ray
  setB(10, 41, 11, "minecraft:gold_block");
  setB(10, 42, 12, "minecraft:end_rod[facing=south]");
  setB(10, 43, 12, "minecraft:lightning_rod[facing=up]");

  // 7. Apex Vertical Ray
  setB(10, 41, 9, "minecraft:gold_block");
  setB(10, 42, 9, "minecraft:end_rod[facing=up]");
  setB(10, 43, 9, "minecraft:end_rod[facing=up]");
  setB(10, 44, 9, "minecraft:lightning_rod[facing=up]");

  return {
    name: "guardian_colossus_apollo",
    seatY: 8,
    anchors: {
      front: [10, 8, 0],
      door: [10, 8, 20],
      spear_tip: [7, 30, 0]
    },
    interiors: [
      { min: [8, 12, 8], max: [12, 15, 12], kind: "vault" }
    ]
  };
}

breaching_tentacle.source:
export const envelope = [13, 32, 13];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 6;
  const rnd = () => api.random();

  // Deterministic 3D voxel grid
  const voxels = new Array(W * H * D).fill(null);
  function setVoxel(x, y, z, block) {
    if (x < 0 || x >= W || y < 0 || y >= H || z < 0 || z >= D) return;
    voxels[x + W * (y + H * z)] = block;
  }
  function getVoxel(x, y, z) {
    if (x < 0 || x >= W || y < 0 || y >= H || z < 0 || z >= D) return null;
    return voxels[x + W * (y + H * z)];
  }

  // PRNG hash for skin mottling
  function hash3(x, y, z) {
    let n = Math.sin(x * 12.9898 + y * 78.233 + z * 37.719) * 43758.5453;
    return n - Math.floor(n);
  }

  const inst = api.instance.index;
  const archetype = inst % 6;

  // Curvature parameters per instance
  const dX = (rnd() - 0.5) * 1.6;
  const dZ = (rnd() - 0.5) * 1.2;
  const hVar = Math.floor(rnd() * 3);

  // 5-point Bézier control points for 6 distinct dynamic kraken poses
  let P0, P1, P2, P3, P4;
  if (archetype === 0) {
    // Aggressive forward lashing strike towards the promenade
    P0 = [6.0, seatY - 1, 8.0];
    P1 = [6.0 + dX * 0.4, seatY + 5, 8.5];
    P2 = [6.0 + dX * 0.8, seatY + 12, 6.0];
    P3 = [6.0 + dX * 1.0, seatY + 17 + hVar, 3.2];
    P4 = [6.0 + dX * 0.7, seatY + 14 + Math.floor(hVar * 0.5), 1.8];
  } else if (archetype === 1) {
    // Towering serpentine S-coil reaching high into the sky
    P0 = [6.0, seatY - 1, 6.5];
    P1 = [4.5 + dX * 0.3, seatY + 6, 7.5];
    P2 = [7.5 - dX * 0.3, seatY + 12, 5.5];
    P3 = [5.5 + dX * 0.4, seatY + 18 + hVar, 4.0];
    P4 = [6.0, seatY + 21 + hVar, 2.5];
  } else if (archetype === 2) {
    // Overhead crushing slam plunging back toward the pavement
    P0 = [6.5, seatY - 1, 7.5];
    P1 = [6.0 + dX * 0.4, seatY + 8, 8.0];
    P2 = [5.5 + dX * 0.6, seatY + 17 + hVar, 5.0];
    P3 = [6.0 - dX * 0.3, seatY + 15, 3.0];
    P4 = [6.5, seatY + 8, 2.0];
  } else if (archetype === 3) {
    // Massive sweeping scythe slashing across the waterfront
    P0 = [6.5, seatY - 1, 7.0];
    P1 = [8.0 + dX * 0.2, seatY + 6, 7.5];
    P2 = [7.0, seatY + 12, 5.5];
    P3 = [4.0 + dX * 0.3, seatY + 16 + hVar, 3.5];
    P4 = [2.5, seatY + 14, 2.2];
  } else if (archetype === 4) {
    // Serpentine undulating whip with high lateral flex
    P0 = [5.5, seatY - 1, 7.5];
    P1 = [7.0 + dX * 0.3, seatY + 5, 6.5];
    P2 = [5.0 - dX * 0.3, seatY + 11, 5.5];
    P3 = [6.5 + dX * 0.3, seatY + 17 + hVar, 3.8];
    P4 = [5.0, seatY + 20 + hVar, 2.0];
  } else {
    // 3D Abyssal corkscrew spiraling out of the deep
    P0 = [6.0, seatY - 1, 6.5];
    P1 = [7.8, seatY + 5, 6.0];
    P2 = [6.5, seatY + 11, 7.8];
    P3 = [4.2, seatY + 17 + hVar, 5.5];
    P4 = [5.8 + dX * 0.4, seatY + 20 + hVar, 3.0 + dZ * 0.2];
  }

  // Kraken palette variations
  const palettes = [
    {
      core: "minecraft:crying_obsidian",
      skin1: "minecraft:dark_prismarine",
      skin2: "minecraft:prismarine",
      accent: "minecraft:warped_wart_block",
      suckerRim: "minecraft:bone_block[axis=y]",
      suckerCore: "minecraft:sea_lantern",
      spine: "minecraft:bone_block[axis=y]",
      spineRoot: "minecraft:dark_prismarine",
      splashFoam: "minecraft:quartz_block",
      splashSea: "minecraft:prismarine_bricks"
    },
    {
      core: "minecraft:crying_obsidian",
      skin1: "minecraft:dark_prismarine",
      skin2: "minecraft:prismarine_bricks",
      accent: "minecraft:dark_prismarine",
      suckerRim: "minecraft:pearlescent_froglight",
      suckerCore: "minecraft:ochre_froglight",
      spine: "minecraft:bone_block[axis=y]",
      spineRoot: "minecraft:dark_prismarine",
      splashFoam: "minecraft:sea_lantern",
      splashSea: "minecraft:prismarine"
    },
    {
      core: "minecraft:prismarine_bricks",
      skin1: "minecraft:prismarine",
      skin2: "minecraft:dark_prismarine",
      accent: "minecraft:prismarine_bricks",
      suckerRim: "minecraft:smooth_sandstone",
      suckerCore: "minecraft:sea_lantern",
      spine: "minecraft:bone_block[axis=y]",
      spineRoot: "minecraft:prismarine_bricks",
      splashFoam: "minecraft:quartz_block",
      splashSea: "minecraft:dark_prismarine"
    },
    {
      core: "minecraft:warped_wart_block",
      skin1: "minecraft:dark_prismarine",
      skin2: "minecraft:warped_wart_block",
      accent: "minecraft:crying_obsidian",
      suckerRim: "minecraft:bone_block[axis=y]",
      suckerCore: "minecraft:verdant_froglight",
      spine: "minecraft:bone_block[axis=y]",
      spineRoot: "minecraft:dark_prismarine",
      splashFoam: "minecraft:white_wool",
      splashSea: "minecraft:prismarine"
    }
  ];
  const palette = palettes[inst % palettes.length];

  // Quartic Bézier evaluation
  function evalBezier(t) {
    const mt = 1 - t;
    const mt2 = mt * mt;
    const mt3 = mt2 * mt;
    const mt4 = mt3 * mt;
    const t2 = t * t;
    const t3 = t2 * t;
    const t4 = t3 * t;

    const c0 = mt4;
    const c1 = 4 * mt3 * t;
    const c2 = 6 * mt2 * t2;
    const c3 = 4 * mt * t3;
    const c4 = t4;

    const x = c0 * P0[0] + c1 * P1[0] + c2 * P2[0] + c3 * P3[0] + c4 * P4[0];
    const y = c0 * P0[1] + c1 * P1[1] + c2 * P2[1] + c3 * P3[1] + c4 * P4[1];
    const z = c0 * P0[2] + c1 * P1[2] + c2 * P2[2] + c3 * P3[2] + c4 * P4[2];

    const d0 = 4 * mt3;
    const d1 = 12 * mt2 * t;
    const d2 = 12 * mt * t2;
    const d3 = 4 * t3;

    const dx = d0 * (P1[0] - P0[0]) + d1 * (P2[0] - P1[0]) + d2 * (P3[0] - P2[0]) + d3 * (P4[0] - P3[0]);
    const dy = d0 * (P1[1] - P0[1]) + d1 * (P2[1] - P1[1]) + d2 * (P3[1] - P2[1]) + d3 * (P4[1] - P3[1]);
    const dz = d0 * (P1[2] - P0[2]) + d1 * (P2[2] - P1[2]) + d2 * (P3[2] - P2[2]) + d3 * (P4[2] - P3[2]);

    const dd0 = 12 * mt2;
    const dd1 = 24 * mt * t;
    const dd2 = 12 * t2;

    const ddx = dd0 * (P2[0] - 2 * P1[0] + P0[0]) + dd1 * (P3[0] - 2 * P2[0] + P1[0]) + dd2 * (P4[0] - 2 * P3[0] + P2[0]);
    const ddy = dd0 * (P2[1] - 2 * P1[1] + P0[1]) + dd1 * (P3[1] - 2 * P2[1] + P1[1]) + dd2 * (P4[1] - 2 * P3[1] + P2[1]);
    const ddz = dd0 * (P2[2] - 2 * P1[2] + P0[2]) + dd1 * (P3[2] - 2 * P2[2] + P1[2]) + dd2 * (P4[2] - 2 * P3[2] + P2[2]);

    return { p: [x, y, z], d: [dx, dy, dz], dd: [ddx, ddy, ddz] };
  }

  // Frenet-Serret orthonormal reference frame
  function computeFrame(d, dd) {
    const lenD = Math.sqrt(d[0] * d[0] + d[1] * d[1] + d[2] * d[2]) || 1;
    const T = [d[0] / lenD, d[1] / lenD, d[2] / lenD];

    const dotDD_T = dd[0] * T[0] + dd[1] * T[1] + dd[2] * T[2];
    let kx = dd[0] - dotDD_T * T[0];
    let ky = dd[1] - dotDD_T * T[1];
    let kz = dd[2] - dotDD_T * T[2];
    let lenK = Math.sqrt(kx * kx + ky * ky + kz * kz);

    let N;
    if (lenK > 0.05) {
      N = [kx / lenK, ky / lenK, kz / lenK];
    } else {
      const ref = [0, 0, -1];
      const dotRef_T = ref[0] * T[0] + ref[1] * T[1] + ref[2] * T[2];
      kx = ref[0] - dotRef_T * T[0];
      ky = ref[1] - dotRef_T * T[1];
      kz = ref[2] - dotRef_T * T[2];
      lenK = Math.sqrt(kx * kx + ky * ky + kz * kz);
      if (lenK > 0.01) {
        N = [kx / lenK, ky / lenK, kz / lenK];
      } else {
        N = [1, 0, 0];
      }
    }

    const B = [
      T[1] * N[2] - T[2] * N[1],
      T[2] * N[0] - T[0] * N[2],
      T[0] * N[1] - T[1] * N[0]
    ];
    const lenB = Math.sqrt(B[0] * B[0] + B[1] * B[1] + B[2] * B[2]) || 1;
    B[0] /= lenB; B[1] /= lenB; B[2] /= lenB;

    return { T, N, B };
  }

  const rBase = 2.6 + rnd() * 0.3;
  const rTip = 0.55 + rnd() * 0.25;
  function radiusAt(t) {
    return rBase * Math.pow(1 - t, 0.85) + rTip * Math.pow(t, 0.85);
  }

  // 1. Rasterize solid fleshy tentacle trunk along spline
  const STEPS = 130;
  for (let s = 0; s <= STEPS; s++) {
    const t = s / STEPS;
    const ev = evalBezier(t);
    const frame = computeFrame(ev.d, ev.dd);
    const r = radiusAt(t);
    const Rv = r * 1.05;
    const Rl = r * 0.95;

    const minX = Math.max(0, Math.floor(ev.p[0] - Rv - 1));
    const maxX = Math.min(W - 1, Math.ceil(ev.p[0] + Rv + 1));
    const minY = Math.max(0, Math.floor(ev.p[1] - Rv - 1));
    const maxY = Math.min(H - 1, Math.ceil(ev.p[1] + Rv + 1));
    const minZ = Math.max(0, Math.floor(ev.p[2] - Rv - 1));
    const maxZ = Math.min(D - 1, Math.ceil(ev.p[2] + Rv + 1));

    for (let x = minX; x <= maxX; x++) {
      for (let y = minY; y <= maxY; y++) {
        for (let z = minZ; z <= maxZ; z++) {
          const dx = x - ev.p[0];
          const dy = y - ev.p[1];
          const dz = z - ev.p[2];

          const u = dx * frame.N[0] + dy * frame.N[1] + dz * frame.N[2];
          const v = dx * frame.B[0] + dy * frame.B[1] + dz * frame.B[2];
          const w = dx * frame.T[0] + dy * frame.T[1] + dz * frame.T[2];

          const q = (u / Rv) * (u / Rv) + (v / Rl) * (v / Rl) + (w / 0.85) * (w / 0.85);
          if (q <= 1.0) {
            let block;
            if (q < 0.35) {
              block = palette.core;
            } else if (q < 0.72) {
              block = palette.skin1;
            } else {
              const h = hash3(x, y, z);
              if (h < 0.55) block = palette.skin1;
              else if (h < 0.85) block = palette.skin2;
              else block = palette.accent;
            }
            setVoxel(x, y, z, block);
          }
        }
      }
    }
  }

  // 2. Ventral Suction Cups along the inner curve
  const numSuckers = 10 + Math.floor(rnd() * 4);
  const doubleRow = rnd() > 0.35;
  for (let i = 0; i < numSuckers; i++) {
    const t = 0.08 + (i / (numSuckers - 1)) * 0.82;
    const ev = evalBezier(t);
    const frame = computeFrame(ev.d, ev.dd);
    const r = radiusAt(t);
    const Rv = r * 1.05;
    const Rl = r * 0.95;

    const offsets = doubleRow ? [-Rl * 0.45, Rl * 0.45] : [(i % 2 === 0 ? 0.3 : -0.3) * Rl * 0.5];
    for (const vOff of offsets) {
      const sx = ev.p[0] + frame.N[0] * (Rv * 0.92) + frame.B[0] * vOff;
      const sy = ev.p[1] + frame.N[1] * (Rv * 0.92) + frame.B[1] * vOff;
      const sz = ev.p[2] + frame.N[2] * (Rv * 0.92) + frame.B[2] * vOff;

      const rDisc = Math.max(0.65, r * 0.42);
      const bxMin = Math.max(0, Math.floor(sx - rDisc - 1));
      const bxMax = Math.min(W - 1, Math.ceil(sx + rDisc + 1));
      const byMin = Math.max(0, Math.floor(sy - rDisc - 1));
      const byMax = Math.min(H - 1, Math.ceil(sy + rDisc + 1));
      const bzMin = Math.max(0, Math.floor(sz - rDisc - 1));
      const bzMax = Math.min(D - 1, Math.ceil(sz + rDisc + 1));

      for (let x = bxMin; x <= bxMax; x++) {
        for (let y = byMin; y <= byMax; y++) {
          for (let z = bzMin; z <= bzMax; z++) {
            const dist = Math.hypot(x - sx, y - sy, z - sz);
            if (dist <= rDisc) {
              if (dist <= rDisc * 0.5) {
                setVoxel(x, y, z, palette.suckerCore);
              } else {
                setVoxel(x, y, z, palette.suckerRim);
              }
            }
          }
        }
      }
    }
  }

  // 3. Dorsal Barbs & Spines along the outer ridge
  const numBarbs = 8 + Math.floor(rnd() * 4);
  for (let i = 0; i < numBarbs; i++) {
    const t = 0.12 + (i / (numBarbs - 1)) * 0.76;
    const ev = evalBezier(t);
    const frame = computeFrame(ev.d, ev.dd);
    const r = radiusAt(t);
    const Rv = r * 1.05;

    const bx = ev.p[0] - frame.N[0] * Rv;
    const by = ev.p[1] - frame.N[1] * Rv;
    const bz = ev.p[2] - frame.N[2] * Rv;

    const spineDir = [
      -frame.N[0] + 0.35 * frame.T[0],
      -frame.N[1] + 0.35 * frame.T[1],
      -frame.N[2] + 0.35 * frame.T[2]
    ];
    const sLen = Math.sqrt(spineDir[0] * spineDir[0] + spineDir[1] * spineDir[1] + spineDir[2] * spineDir[2]) || 1;
    spineDir[0] /= sLen; spineDir[1] /= sLen; spineDir[2] /= sLen;

    const barbLen = 1.2 + (1.0 - Math.abs(t - 0.45) * 1.7) * 1.4;
    for (let k = 0; k <= barbLen; k += 0.55) {
      const px = Math.round(bx + spineDir[0] * k);
      const py = Math.round(by + spineDir[1] * k);
      const pz = Math.round(bz + spineDir[2] * k);
      if (k > barbLen * 0.55) {
        setVoxel(px, py, pz, palette.spine);
      } else {
        setVoxel(px, py, pz, palette.spineRoot);
      }
    }
  }

  // 4. Base Splash Ring & Wave Crests at water surface
  const x0 = P0[0];
  const z0 = P0[2];
  const rSplash = rBase + 1.2 + rnd() * 0.4;
  const splashPhase = rnd() * Math.PI * 2;

  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const dist = Math.hypot(x - x0, z - z0);
      if (dist <= rSplash + 0.4 && dist >= rBase * 0.5) {
        const angle = Math.atan2(z - z0, x - x0);
        const crest = Math.sin(angle * 3 + splashPhase) * 0.8 + Math.cos(angle * 2) * 0.5;
        const topY = Math.round(seatY + 1 + crest);
        for (let y = seatY - 1; y <= topY; y++) {
          if (y === topY) {
            setVoxel(x, y, z, rnd() > 0.35 ? palette.splashFoam : palette.splashSea);
          } else {
            setVoxel(x, y, z, palette.splashSea);
          }
        }
      }
    }
  }

  // 5. Dynamic splash tendrils / spray spikes
  const numSpikes = 3 + Math.floor(rnd() * 3);
  for (let k = 0; k < numSpikes; k++) {
    const ang = rnd() * Math.PI * 2;
    const sDist = rBase + 0.6 + rnd() * 0.8;
    const sx = Math.round(x0 + Math.cos(ang) * sDist);
    const sz = Math.round(z0 + Math.sin(ang) * sDist);
    const spikeH = Math.min(H - 2, seatY + 2 + Math.floor(rnd() * 3));
    for (let y = seatY; y <= spikeH; y++) {
      setVoxel(sx, y, sz, y === spikeH ? palette.splashFoam : palette.splashSea);
    }
  }

  // 6. Terrain Conformance: Fill downward to ground/seabed for every column
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      let minY = -1;
      for (let y = 0; y < H; y++) {
        if (getVoxel(x, y, z) !== null) {
          minY = y;
          break;
        }
      }

      if (minY !== -1 && minY <= seatY + 4) {
        const hAt = api.heightAt(x, z);
        const yTarget = Math.max(0, Math.min(H - 1, seatY + Math.floor(hAt)));
        const distToBase = Math.hypot(x - x0, z - z0);
        const skirtBlock = distToBase <= rBase * 1.15 ? palette.skin1 : palette.splashSea;

        if (yTarget < minY) {
          for (let y = minY - 1; y >= yTarget; y--) {
            setVoxel(x, y, z, skirtBlock);
          }
        } else if (yTarget > minY) {
          for (let y = minY; y <= yTarget; y++) {
            if (getVoxel(x, y, z) === null) {
              setVoxel(x, y, z, skirtBlock);
            }
          }
        }
      }
    }
  }

  // 7. Single 6-connected component verification (BFS)
  const visited = new Uint8Array(W * H * D);
  const queue = [];

  let startX = Math.round(x0);
  let startZ = Math.round(z0);
  let startY = seatY;
  while (startY < H && getVoxel(startX, startY, startZ) === null) startY++;
  if (startY >= H) {
    for (let y = 0; y < H; y++) {
      if (getVoxel(startX, y, startZ) !== null) { startY = y; break; }
    }
  }

  if (getVoxel(startX, startY, startZ) !== null) {
    const sIdx = startX + W * (startY + H * startZ);
    visited[sIdx] = 1;
    queue.push(startX, startY, startZ);

    let head = 0;
    while (head < queue.length) {
      const qx = queue[head++];
      const qy = queue[head++];
      const qz = queue[head++];

      const neighbors = [
        [qx + 1, qy, qz], [qx - 1, qy, qz],
        [qx, qy + 1, qz], [qx, qy - 1, qz],
        [qx, qy, qz + 1], [qx, qy, qz - 1]
      ];

      for (const [nx, ny, nz] of neighbors) {
        if (nx >= 0 && nx < W && ny >= 0 && ny < H && nz >= 0 && nz < D) {
          const nIdx = nx + W * (ny + H * nz);
          if (!visited[nIdx] && voxels[nIdx] !== null) {
            visited[nIdx] = 1;
            queue.push(nx, ny, nz);
          }
        }
      }
    }

    // Drop any disconnected fragments
    for (let x = 0; x < W; x++) {
      for (let y = 0; y < H; y++) {
        for (let z = 0; z < D; z++) {
          const idx = x + W * (y + H * z);
          if (voxels[idx] !== null && !visited[idx]) {
            voxels[idx] = null;
          }
        }
      }
    }
  }

  // 8. Emit blocks to world
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const b = getVoxel(x, y, z);
        if (b) {
          api.set(x, y, z, b);
        }
      }
    }
  }

  function clampAnchor(pt) {
    return [
      Math.max(0, Math.min(W - 1, Math.round(pt[0]))),
      Math.max(0, Math.min(H - 1, Math.round(pt[1]))),
      Math.max(0, Math.min(D - 1, Math.round(pt[2])))
    ];
  }

  return {
    name: "breaching_tentacle",
    seatY: seatY,
    anchors: {
      front: clampAnchor([P4[0], P4[1], 0]),
      tip: clampAnchor([P4[0], P4[1], P4[2]]),
      base: clampAnchor([x0, seatY, z0])
    }
  };
}
